#!/usr/bin/env python3
"""Generated by CodeRig. Do not edit; regenerate with `coderig connect`.

Runs the sensors from sensors.json (served by Launchpad's registry).

    python .coderig/verify.py --stop [--agent A]   the agent's finish hook (Claude Code / Codex Stop,
                                    Gemini AfterAgent, Cursor stop): failures go back to the agent
    python .coderig/verify.py           run every sensor once and print the result (exit 1 on failure)
        --only ID[,ID]                  run just these sensors, e.g. --only format
    python .coderig/verify.py --fix ID  run a sensor's fix command (e.g. the formatter), then re-check it
"""
import hashlib
import json
import re
import shlex
import shutil
import subprocess
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
sys.path.insert(0, str(HERE))
import hookio  # noqa: E402  (generated next to this file)

CONFIG = json.loads((HERE / "sensors.json").read_text(encoding="utf-8"))
STATE = HERE / "state" / "verify.json"
LOG = HERE / "state" / "runs.jsonl"
START = time.time()
MAX_CHARS = 6000
MAX_LINES = 60


# ── running a sensor ─────────────────────────────────────────────────────────

def sensor_dir(sensor):
    """Where the sensor's commands run: its module folder (`cwd`) inside the repository, else the root."""
    folder = (ROOT / sensor["cwd"]).resolve() if sensor.get("cwd") else ROOT
    return folder if folder == ROOT or ROOT in folder.parents else ROOT


def command(sensor, text):
    """The argv for one of the sensor's commands: on this machine, or in its container."""
    args = shlex.split(text)
    docker = sensor.get("docker")
    if not docker:
        found = shutil.which(args[0])          # resolves mvn.cmd and friends on Windows
        return ([found] + args[1:]) if found else args
    mount = docker.get("workdir", "/work")
    inside = mount + ("/" + sensor_dir(sensor).relative_to(ROOT).as_posix() if sensor_dir(sensor) != ROOT else "")
    wrapped = ["docker", "run", "--rm", "-v", f"{ROOT}:{mount}"]
    cache = docker.get("cache")
    if cache:
        wrapped += ["-v", f"{cache['volume']}:{cache['path']}"]
    return wrapped + ["-w", inside, docker["image"]] + args


# Build-tool boilerplate, matched by what the line STARTS with. (Matching anywhere in the line once
# dropped a real violation because its message quoted a URL containing one of these words.)
NOISE = re.compile(
    r"^\[(ERROR|INFO)\] ?("
    r"->? ?\[Help \d+\]|\[Help \d+\]|Re-run Maven|To see the full stack trace|"
    r"For more information about the errors|Please refer to|BUILD FAILURE)"
    # the application's own log lines (a timestamp then a level), which a test run prints amid the results
    r"|^\d{4}-\d{2}-\d{2}T[\d:.]+Z?\s+(WARN|INFO|DEBUG|TRACE)\b")


def trim(text, workdir=None):
    """Keep the lines that explain the failure, plus the indented detail under them, else all.
    Build-tool boilerplate is dropped, and container paths are shown relative to the repository."""
    if workdir:
        text = text.replace(workdir.rstrip("/") + "/", "")
    lines = [ln for ln in text.splitlines()
             if not NOISE.match(ln) and ln.strip() not in ("[ERROR]", "[ERROR] ")]
    keep = set()
    for i, line in enumerate(lines):
        if line.startswith("[ERROR]") or "<<<" in line or "FAIL" in line:
            keep.add(i)
            j = i + 1
            while j < len(lines) and lines[j][:1] in (" ", "\t") and j - i <= 3:
                keep.add(j)
                j += 1
    chosen = [lines[i] for i in sorted(keep)] if keep else lines
    return "\n".join(chosen[-MAX_LINES:])[-MAX_CHARS:]


def applies(sensor):
    """A sensor with `applies_when` runs only if one of those paths exists at the repository root."""
    wanted = sensor.get("applies_when") or []
    return not wanted or any(any(ROOT.glob(pattern)) for pattern in wanted)


def run_command(sensor, text):
    """Returns (status, output): status is ok | failed | error. `error` means the check could not
    run (no Docker, no tool, timeout); the agent cannot fix that, so it is not fed back."""
    if sensor.get("docker") and not shutil.which("docker"):
        return "error", "Docker is not installed or not on PATH, so this check could not run."
    try:
        done = subprocess.run(
            command(sensor, text), cwd=ROOT if sensor.get("docker") else sensor_dir(sensor), capture_output=True,
            text=True, encoding="utf-8", errors="replace", timeout=sensor.get("timeout", 300),
        )
    except FileNotFoundError as exc:
        return "error", f"cannot run: {exc}"
    except subprocess.TimeoutExpired:
        return "error", f"timed out after {sensor.get('timeout', 300)}s"
    output = (done.stdout or "") + (done.stderr or "")
    if sensor.get("docker") and (done.returncode == 125 or "daemon" in output.lower() and "connect" in output.lower()):
        # Docker itself failed (its own exit code, or no daemon): the check never ran, and the agent
        # cannot fix that, so it is reported to the developer instead of being fed back.
        return "error", "Docker could not run the check (is Docker Desktop running?). " + trim(output)[-300:]
    workdir = (sensor.get("docker") or {}).get("workdir", "/work") if sensor.get("docker") else None
    return ("ok" if done.returncode == 0 else "failed"), trim(output, workdir)


def timed(sensor):
    started = time.time()
    status, output = run_command(sensor, sensor["run"])
    return {"sensor": sensor, "status": status, "output": output, "seconds": round(time.time() - started, 1)}


# ── what has changed ─────────────────────────────────────────────────────────

def git(*args):
    try:
        done = subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True,
                              encoding="utf-8", errors="replace")
    except FileNotFoundError:
        return ""
    return done.stdout if done.returncode == 0 else ""


def anchor():
    """The commit this branch's work is measured against: where it left the default branch.

    Comparing with it, not with HEAD, means committing does not hide a change from the sensors.
    (The agent's own rules tell it to commit, so a check against HEAD would see a clean tree
    after the agent's last commit and skip the checks on exactly the work that needs them.)"""
    for ref in ("origin/HEAD", "origin/main", "origin/master", "main", "master"):
        if git("rev-parse", "--verify", "--quiet", ref).strip():
            base = git("merge-base", "HEAD", ref).strip()
            if base:
                return base
    return "HEAD"


def ignored(path):
    return any(path == p.rstrip("/") or path.startswith(p) for p in CONFIG.get("ignore_paths", []))


def excludes():
    """Git pathspecs that leave out CodeRig's own generated files."""
    return [f":(exclude){p.rstrip('/')}" for p in CONFIG.get("ignore_paths", [])]


def fingerprint():
    """What this branch has changed, committed or not, that the sensors care about.

    "unknown": not a git repository, so run the sensors to be safe.
    "clean":   no change against the branch's base apart from CodeRig's own files (a plan-only or
               question-only turn on a branch with no work of its own).
    otherwise: a hash of the diff against the base plus the untracked files, so a change that has
               already passed is not checked again, whether or not it has been committed since.
    """
    if git("rev-parse", "--is-inside-work-tree").strip() != "true":
        return "unknown"
    diff = git("diff", anchor(), "--", ".", *excludes())
    untracked = [n for n in git("ls-files", "--others", "--exclude-standard").splitlines()
                 if n and not ignored(n)]
    if not diff and not untracked:
        return "clean"
    parts = [diff]
    for path in sorted(untracked):
        try:
            info = (ROOT / path).stat()
            parts.append(f"{path}:{info.st_size}:{info.st_mtime_ns}")
        except OSError:
            parts.append(f"{path}:deleted")
    return hashlib.sha256("\n".join(parts).encode("utf-8")).hexdigest()


# ── the loop ─────────────────────────────────────────────────────────────────

def load_state():
    try:
        return json.loads(STATE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def save_state(state):
    STATE.parent.mkdir(parents=True, exist_ok=True)
    STATE.write_text(json.dumps(state), encoding="utf-8")


def log_run(session, outcome, results, attempt=None):
    """One JSON line per stop in .coderig/state/runs.jsonl: what ran, what it said, how long it took."""
    record = {
        "time": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "session": session,
        "outcome": outcome,
        "seconds": round(time.time() - START, 1),
        "sensors": [{
            "id": r["sensor"]["id"],
            "status": r["status"],
            "seconds": r["seconds"],
            "detail": r["output"][:800] if r["status"] != "ok" else "",
        } for r in results],
    }
    if attempt is not None:
        record["attempt"] = attempt
    try:
        LOG.parent.mkdir(parents=True, exist_ok=True)
        if LOG.exists() and LOG.stat().st_size > 1_000_000:
            LOG.replace(LOG.with_suffix(".jsonl.1"))
        with LOG.open("a", encoding="utf-8") as handle:
            # A project's own "no http:// URLs" check scans every file, this log included, and a
            # build tool's output quotes URLs. : is ':' to any JSON reader and is not a URL.
            handle.write(json.dumps(record, ensure_ascii=False).replace("http://", "http\\u003a//") + "\n")
    except OSError:
        pass                                    # logging must never break the hook


def sensors():
    return [s for s in CONFIG["sensors"] if applies(s)]


def report(results):
    lines = []
    for r in results:
        s = r["sensor"]
        if r["status"] == "ok":
            continue
        label = "FAILED" if r["status"] == "failed" else "COULD NOT RUN"
        lines.append(f"[{s['id']}] {s.get('description', '')} - {label}")
        lines.append(r["output"] or "(no output)")
        if r["status"] == "failed" and s.get("hint"):
            lines.append("How to fix: " + " ".join(s["hint"].split()))
        lines.append("")
    return "\n".join(lines).rstrip()


def blocking_failures(results):
    return [r for r in results if r["status"] == "failed" and r["sensor"].get("blocking", True)]


def hook():
    agent = hookio.agent()
    session = hookio.read_event()["session"] or "default"
    limit = CONFIG.get("loop", {}).get("max_iterations", 3)
    state = load_state()
    entry = state.get(session) or {"attempts": 0}

    # Nothing to check: the agent only asked a question or wrote a plan, or this exact change
    # already passed. Skipping saves minutes of build on every turn that did not touch the code.
    print_fp = fingerprint()
    if print_fp == "clean":
        state.pop(session, None)
        save_state(state)
        log_run(session, "skipped-clean", [])
        return 0
    passed = state.get("_passed", [])
    if print_fp != "unknown" and print_fp in passed:
        log_run(session, "skipped-unchanged", [])
        return 0

    results = [timed(s) for s in sensors()]
    failed = blocking_failures(results)
    broken = [r for r in results if r["status"] == "error"]

    if not failed:
        state.pop(session, None)
        if print_fp != "unknown":
            # Remember what passed, for every session on this repository. Fingerprint the tree as
            # the sensors left it (a build may write files) so the next stop compares like with like.
            state["_passed"] = (passed + [fingerprint()])[-20:]
        save_state(state)
        log_run(session, "error" if broken else "pass", results)
        if broken:
            return hookio.notice(agent, "Harness checks could not run:\n" + report(broken))
        return 0

    entry["attempts"] += 1
    if entry["attempts"] > limit:
        state.pop(session, None)
        save_state(state)
        log_run(session, "exhausted", results, attempt=entry["attempts"])
        return hookio.notice(agent,
            f"Harness: sensors still failing after {limit} attempts. Stopping so you can decide.\n"
            + report(failed))

    state[session] = entry
    save_state(state)
    log_run(session, "feedback", results, attempt=entry["attempts"])
    return hookio.feedback(agent,
        f"HARNESS FEEDBACK (attempt {entry['attempts']} of {limit}). Fix these, then finish again; "
        f"the checks re-run automatically.\n\n" + report(failed) + "\n")


def option(name):
    if name in sys.argv:
        position = sys.argv.index(name)
        return sys.argv[position + 1] if position + 1 < len(sys.argv) else None
    return None


def fix(sensor_id):
    sensor = next((s for s in CONFIG["sensors"] if s["id"] == sensor_id), None)
    if sensor is None:
        print(f"No sensor '{sensor_id}'. Known: {', '.join(s['id'] for s in CONFIG['sensors'])}")
        return 1
    if not sensor.get("fix"):
        print(f"Sensor '{sensor_id}' has no fix command; fix what it reports by hand.")
        return 1
    status, output = run_command(sensor, sensor["fix"])
    print(f"fix {sensor_id}: {status}")
    if status != "ok":
        print(output)
        return 1
    result = timed(sensor)
    print(f"re-check {sensor_id}: {result['status']}")
    if result["status"] != "ok":
        print(result["output"])
    return 0 if result["status"] == "ok" else 1


def main():
    if "--stop" in sys.argv:
        return hook()
    if "--fix" in sys.argv:
        return fix(option("--fix") or "")
    only = option("--only")
    wanted = set(only.split(",")) if only else None
    results = [timed(s) for s in sensors() if wanted is None or s["id"] in wanted]
    for r in results:
        print(f"{r['sensor']['id']:<14} {r['status']:<7} {r['seconds']}s")
    text = report(results)
    if text:
        print("\n" + text)
    return 0 if all(r["status"] == "ok" for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())
